case=f[(f.split=='test')&f.dataset.isin(DS)].reset_index(drop=True);idx={i:v for v,i in enumerate(case.source_index)};clusters,codes=np.unique(case.cluster,return_inverse=True);B=2000;rng=np.random.default_rng(20261019);W0=rng.exponential(size=(B,len(clusters)))[:,codes]*case.weight.to_numpy()[None,:]
for _,ii in case.groupby(['backbone','dataset','stratum']).indices.items():
 w=case.weight.to_numpy()[ii]
