def table(x):
 names={'model':'Judge','backbone':'Backbone','dataset':'Dataset','method':'Selector','regime':'Threshold policy','policy':'Threshold policy','f1_disagreement':'Disagreement-only F1 (%)','f1_all':'All-validation F1 (%)','delta_f1_pp':'F1 change (pp)','precision_all':'Precision (%)','recall_all':'Recall (%)','training_rows':'All training rows','helpful':'Helpful','harmful':'Harmful','unchanged':'Unchanged','lower':'95% lower','upper':'95% upper','baseline':'Compared with'}
